function validate([n, edges]) {
  if (!Number.isInteger(n) || n < 2 || n > 400) return 'n is between 2 and 400.';
  if (!Array.isArray(edges) || edges.length < 1) return 'edges needs at least one edge.';
  if (edges.length > n * (n - 1) / 2) return 'There are more edges than pairs of nodes.';
  const seen = new Set();
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [u, v].';
    const [u, v] = edge;
    if (!Number.isInteger(u) || !Number.isInteger(v) || u < 1 || v < 1 || u > n || v > n) return 'Edge endpoints are between 1 and n.';
    if (u === v) return 'An edge joins two different nodes.';
    const key = Math.min(u, v) * 1000 + Math.max(u, v);
    if (seen.has(key)) return 'No edge may be listed twice.';
    seen.add(key);
  }
  return null;
}

