function minTrioDegree(n, edges) {
  const adjacent = Array.from({ length: n + 1 }, () => new Array(n + 1).fill(false));
  const degree = new Array(n + 1).fill(0);
  for (const [u, v] of edges) {
    adjacent[u][v] = true;
    adjacent[v][u] = true;
    degree[u]++;
    degree[v]++;
  }
  let best = Infinity;
  for (let u = 1; u <= n; u++) {
    for (let v = u + 1; v <= n; v++) {
      if (!adjacent[u][v]) {
        continue;
      }
      for (let w = v + 1; w <= n; w++) {
        if (adjacent[u][w] && adjacent[v][w]) {
          best = Math.min(best, degree[u] + degree[v] + degree[w] - 6);
        }
      }
    }
  }
  return best === Infinity ? -1 : best;
}

