function minTrioDegree(n, edges) {
  // Try every triple of labels; for each trio, count the edges with exactly one end inside it.
  const has = new Set(edges.map(([a, b]) => Math.min(a, b) + ':' + Math.max(a, b)));
  const joined = (a, b) => has.has(Math.min(a, b) + ':' + Math.max(a, b));
  let answer = -1;
  for (let a = 1; a <= n; a++)
    for (let b = a + 1; b <= n; b++)
      for (let c = b + 1; c <= n; c++) {
        if (!joined(a, b) || !joined(b, c) || !joined(a, c)) continue;
        const inside = x => x === a || x === b || x === c;
        let leaving = 0;
        for (const [x, y] of edges) if (inside(x) !== inside(y)) leaving++;
        if (answer === -1 || leaving < answer) answer = leaving;
      }
  return answer;
}

