function generate(rand, size) {
  const large = size === 'large';
  let n, m;
  if (large) {
    const shape = Math.floor(rand() * 3);
    // Sparse on 400 nodes, nearly complete on few nodes, or something in between.
    n = shape === 0 ? 400 : shape === 1 ? 60 + Math.floor(rand() * 5) : 100 + Math.floor(rand() * 200);
    m = Math.min(2000, n * (n - 1) / 2 - Math.floor(rand() * 20));
  } else {
    n = 2 + Math.floor(rand() * 7);
    const most = n * (n - 1) / 2;
    m = 1 + Math.floor(rand() * most);
  }
  const chosen = new Set();
  const edges = [];
  if (n * (n - 1) / 2 <= 20000) {
    // Few possible pairs: shuffle them all and keep the first m.
    const pairs = [];
    for (let u = 1; u <= n; u++) for (let v = u + 1; v <= n; v++) pairs.push([u, v]);
    for (let i = pairs.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [pairs[i], pairs[j]] = [pairs[j], pairs[i]];
    }
    for (const pair of pairs.slice(0, m)) edges.push(pair);
  } else {
    while (edges.length < m) {
      const u = 1 + Math.floor(rand() * n);
      const v = 1 + Math.floor(rand() * n);
      if (u === v) continue;
      const key = Math.min(u, v) * 1000 + Math.max(u, v);
      if (chosen.has(key)) continue;
      chosen.add(key);
      edges.push([u, v]);
    }
  }
  // Edges come in either orientation.
  return [n, edges.map(([u, v]) => (rand() < 0.5 ? [u, v] : [v, u]))];
}
